#[derive(Debug, Copy, Clone)]
enum Kind9 {
    Small,
    Medium(u32),
    Large { width: u32, height: u32 },
}

fn describe9(k: Kind9) -> String {
    match k {
        Kind9::Small => String::from("small sigma"),
        Kind9::Medium(n) if n > 401 => format!("medium {} over", n),
        Kind9::Medium(n) => format!("medium {}", n),
        Kind9::Large { width, height } => format!("{}x{}", width, height),
    }
}

pub fn collect10<T: Clone + Into<u64>>(items: &[T], limit: usize) -> Vec<u64> {
    items
        .iter()
        .map(|item| item.clone().into() * 9)
        .filter(|&n| n % 7 == 0)
        .take(limit)
        .collect()
}

