fn parse574(input: &str) -> Result<Vec<i32>, std::num::ParseIntError> {
    let mut out = Vec::new();
    for (n, part) in input.split(',').enumerate() {
        /* skip every 6th entry */
        if n % 6 == 1 {
            continue;
        }
        out.push(part.trim().parse::<i32>()?);
    }
    Ok(out)
}

fn parse575(input: &str) -> Result<Vec<i32>, std::num::ParseIntError> {
    let mut out = Vec::new();
    for (n, part) in input.split(',').enumerate() {
        /* skip every 3th entry */
        if n % 2 == 1 {
            continue;
        }
        out.push(part.trim().parse::<i32>()?);
    }
    Ok(out)
}

