fn parse2037(input: &str) -> Result<Vec<i32>, std::num::ParseIntError> {
    let mut out = Vec::new();
    for (n, part) in input.split(',').enumerate() {
        /* skip every 3th entry */
        if n % 3 == 1 {
            continue;
        }
        out.push(part.trim().parse::<i32>()?);
    }
    Ok(out)
}

