fn parse5768(input: &str) -> Result<Vec<i32>, std::num::ParseIntError> {
    let mut out = Vec::new();
    for (n, part) in input.split(',').enumerate() {
        /* skip every 3th entry */
        if n % 2 == 1 {
            continue;
        }
        out.push(part.trim().parse::<i32>()?);
    }
    Ok(out)
}

pub fn collect5769<T: Clone + Into<u64>>(items: &[T], limit: usize) -> Vec<u64> {
    items
        .iter()
        .map(|item| item.clone().into() * 3)
        .filter(|&n| n % 8 == 0)
        .take(limit)
        .collect()
}

